                    @include flexCenter(row, center);
                    border-image-slice: 50 50 50 50 fill;
                    border-image-width: 25px 25px 25px 25px;
                    border-image-outset: 20px 20px 20px 20px;
                    border-image-repeat: repeat repeat;
                    border-image-source: var(--svg);
                    border-style: solid;

                    div {
                        height: auto;
                        min-height: 100%;

                        .flower-img {
                            width: 100%;
                            height: auto;
                            margin: 15px 0;
                            border-radius: 10px;
                            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);

                        }
                    }

                    h3 {
                        font-size: 26px;
                        margin-bottom: 15px;
                        font-weight: 700;
                        color: #2c3e50;
                        position: relative;
                        display: inline-block;

                        &::after {
                            content: '';
                            position: absolute;
                            bottom: -5px;
                            left: 0;
                            width: 50px;
                            height: 3px;
                            background: $currentPageLinear;
                            border-radius: 2px;

                        }
                    }

                    p {
                        font-size: 16px;
                        font-weight: 400;
                        color: #555;
                        line-height: 1.7;
                        overflow: hidden;
                        text-overflow: ellipsis;
                        display: -webkit-box;
                        // 限制显示行数
                        -webkit-line-clamp: 2;
                        -webkit-box-orient: vertical;
                    }

                    .flower-info {
                        padding-top: 15px;
                        border-top: 1px solid #e0e6ed;
                        font-size: 14px;
                        color: #7e8c9a;
                        display: flex;
                        justify-content: space-between;

                        strong {
                            color: $primary-sub;
                        }
                    }


                }
            }

        }
    }


    .zoomed {
        position: fixed !important;
        top: 50% !important;
        left: 50% !important;
        transform: translate(-50%, -50%) !important;
        width: 90vw !important;
        height: 90vh !important;
        z-index: 1000 !important;
        padding: 20px !important;
        max-width: 900px;
    }

    .zoomed .card-main {
        height: auto;
        max-height: 90vh;
        overflow-y: auto;
        padding: 40px;

        img {
            max-height: 50vh;
        }
    }

    .zoomed p {
        -webkit-line-clamp: unset !important;
        overflow-y: auto;
    }

    .overflow {
        overflow: hidden;
    }

    .opacity-0 {
        opacity: 0.3;
        pointer-events: none;
        transition: opacity 0.3s ease;
    }


    .close-btn {
        position: absolute;
        top: 20px;
        right: 20px;
        background: $assistance-9;
        border: none;
        width: 40px;
        height: 40px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: pointer;
        font-size: 20px;
        color: $general-white;
        transition: all 0.3s ease;
        z-index: 1001;
    }

    .close-btn:hover {
        transform: rotate(90deg);
    }

    @media (max-width: 768px) {
        .card-wrapper {
            grid-template-columns: 1fr;
        }

        .card-main {
            padding: 20px;
        }

        .header h1 {
            font-size: 32px;
        }

        .zoomed {
            width: 95vw !important;
            height: 95vh !important;
            padding: 10px !important;
        }

        .zoomed .card-main {
            padding: 25px;
        }
    }

    //底部版权
    .footer {
        width: 100%;
        @include flexCenter(column, center);
        border-top-left-radius: 3rem;
        border-top-right-radius: 3rem;
        padding: 0.9rem 0;
        position: relative;
        overflow: hidden;
        font-size: 0.8rem;
        z-index: 1;
        font-family: 'gtpy';
        margin: auto;
        background: linear-gradient(45deg, $assistance-1, $assistance-2, $assistance-4);
        animation: hueRotate 10s infinite alternate;

        @keyframes hueRotate {
            100% {
                filter: hue-rotate(360deg);
            }
        }

        p {
            color: $general-white;
            margin-bottom: 1rem;
        }
    }
}
</style>
